export default "<template>\n  <ev-chart\n    :data=\"chartData\"\n    :options=\"chartOptions\"\n  />\n</template>\n\n<script>\n  import dayjs from 'dayjs';\n\n  export default {\n    setup() {\n      const time = dayjs().format('YYYY-MM-DD HH:mm:ss');\n      const chartData = {\n        series: Array(1000).fill(0).reduce((acc, _, idx) => {\n          acc[`series${idx + 1}`] = { name: `series#${idx + 1}`, fill: true, point: true };\n          return acc;\n        }, {}),\n        groups: [Array(1000).fill(0).map((_, idx) => `series${idx + 1}`)],\n        labels: Array(10).fill(0).map((_, index) => dayjs(time).add(index, 'day')),\n        data: Array(1000).fill(0).reduce((acc, _, idx) => {\n          acc[`series${idx + 1}`] = Array(10).fill(0).map(() => Math.floor(Math.random() * 100));\n          return acc;\n        }, {}),\n      };\n\n      const chartOptions = {\n        type: 'line',\n        width: '100%',\n        title: {\n          text: 'Chart Title',\n          show: true,\n        },\n        legend: {\n          show: true,\n          position: 'right',\n          virtualScroll: true,\n        },\n        tooltip: {\n          use: true,\n        },\n        axesX: [{\n          type: 'time',\n          showGrid: false,\n          timeFormat: 'MM/DD',\n          interval: 'day',\n          labelStyle: {\n            color: '#A4A4A4',\n            fontSize: '11px',\n            fontFamily: 'Roboto',\n          },\n        }],\n        axesY: [{\n          type: 'linear',\n          showGrid: true,\n          startToZero: true,\n          autoScaleRatio: 0.1,\n          labelStyle: {\n            color: '#A4A4A4',\n            fontSize: '11px',\n            fontFamily: 'Roboto',\n          },\n        }],\n      };\n\n      return {\n        chartData,\n        chartOptions,\n      };\n    },\n  };\n</script>\n\n<style lang=\"scss\">\n</style>\n";