export default "<template>\n  <div class=\"case\">\n    <ev-chart\n      :data=\"chartData\"\n      :options=\"chartOptions\"\n    />\n    <div class=\"description\">\n      <div class=\"row\">\n        <span>Y축 라벨 개수</span>\n        <ev-input-number\n          v-model=\"yLabelCount\"\n          :min=\"1\"\n          :max=\"100\"\n        />\n      </div>\n      <div class=\"row\">\n        <span>소수점 자릿수</span>\n        <ev-input-number\n          v-model=\"decimalPoint\"\n          :min=\"0\"\n          :max=\"10\"\n        />\n      </div>\n    </div>\n  </div>\n</template>\n\n<script>\nimport { reactive, ref, watch } from 'vue';\n  import dayjs from 'dayjs';\n\n  export default {\n    setup() {\n      const chartOptions = {\n        type: 'heatMap',\n        width: '100%',\n        height: '100%',\n        title: {\n          show: false,\n        },\n        indicator: {\n          use: false,\n        },\n        axesX: [{\n          type: 'time',\n          timeFormat: 'HH:mm:ss',\n          categoryMode: true,\n          showGrid: true,\n          interval: {\n            time: 5,\n            unit: 'second',\n          },\n          labelStyle: {\n            alignToGridLine: true,\n          },\n        }],\n        axesY: [{\n          type: 'step',\n          showGrid: true,\n          labelStyle: {\n            alignToGridLine: true,\n          },\n        }],\n        heatMapColor: {\n          min: '#CAF0F8',\n          max: '#03045E',\n          rangeCount: 8,\n          stroke: {\n            show: true,\n            color: '#FFFFFF',\n            lineWidth: 1,\n          },\n        },\n        tooltip: {\n          use: true,\n        },\n      };\n\n      const yLabelCount = ref(20);\n      const decimalPoint = ref(0);\n      const yLabels = [];\n\n      const currentTime = dayjs();\n      const xLabels = [\n        dayjs(currentTime),\n        dayjs(currentTime).add(5, 'second'),\n        dayjs(currentTime).add(10, 'second'),\n        dayjs(currentTime).add(15, 'second'),\n        dayjs(currentTime).add(20, 'second'),\n        dayjs(currentTime).add(25, 'second'),\n        dayjs(currentTime).add(30, 'second'),\n      ];\n\n      const chartData = reactive({\n        series: {\n          series1: {\n            name: 'series#1',\n            showValue: {\n              use: false,\n            },\n          },\n        },\n        labels: {\n          x: xLabels,\n          y: yLabels,\n        },\n        data: {\n          series1: [],\n        },\n      });\n\n      const setChartRandomData = () => {\n        chartData.data.series1 = [];\n\n        const labelX = chartData.labels.x;\n        const labelY = chartData.labels.y;\n        for (let ix = 0; ix < labelX.length; ix++) {\n          for (let iy = 0; iy < labelY.length; iy++) {\n            const randomCount = Math.floor(Math.random() * 50) + 1;\n            chartData.data.series1.push({\n              x: dayjs(labelX[ix]),\n              y: labelY[iy],\n              value: randomCount,\n            });\n          }\n        }\n      };\n\n      watch([yLabelCount, decimalPoint], () => {\n        yLabels.splice(0, yLabels.length);\n        yLabels.push(0);\n\n        for (let i = 1; i <= yLabelCount.value; i++) {\n          yLabels.push(i / 10 ** decimalPoint.value);\n        }\n\n        setChartRandomData();\n      }, {\n        immediate: true,\n      });\n\n      return {\n        chartData,\n        chartOptions,\n        yLabelCount,\n        decimalPoint,\n      };\n    },\n  };\n</script>\n\n<style lang=\"scss\" scoped>\n.case {\n  display: flex;\n  height: 100%;\n  flex-direction: column;\n\n  :deep(.ev-chart) {\n    flex: auto;\n  }\n\n  .description {\n    display: flex;\n    flex-direction: column;\n    gap: 12px;\n  }\n\n  .row {\n    display: flex;\n    flex-direction: row;\n    align-items: center;\n    gap: 12px;\n  }\n}\n</style>\n";