export default "<template>\n  <ev-chart-group :options=\"{ syncHover }\">\n    <ev-chart\n      ref=\"chart\"\n      v-model:selectedLabel=\"defaultSelectLabel\"\n      :data=\"chartData1\"\n      :options=\"chartOptions1\"\n      @click=\"onClick\"\n    />\n    <ev-chart\n      v-model:selectedLabel=\"defaultSelectLabel\"\n      :data=\"chartData2\"\n      :options=\"chartOptions2\"\n      @click=\"onClick\"\n    />\n    <ev-chart\n      v-model:selectedLabel=\"defaultSelectLabel\"\n      :data=\"chartData3\"\n      :options=\"chartOptions3\"\n      @click=\"onClick\"\n    />\n    <ev-chart\n      v-model:selectedLabel=\"defaultSelectLabel\"\n      :data=\"chartData4\"\n      :options=\"chartOptions4\"\n      @click=\"onClick\"\n    />\n    <div class=\"description\">\n      <ev-toggle v-model=\"syncHover\" />\n      <span>그룹 호버 동기화</span>\n      <br>\n      <br>\n      <span>차트별 호버 동기화</span>\n      <br>\n      <br>\n      <div class=\"hover-options\">\n        <span>첫번째 차트</span>\n        <ev-toggle v-model=\"syncHoverChart1\" />\n        <span>두번째 차트</span>\n        <ev-toggle v-model=\"syncHoverChart2\" />\n        <span>세번째 차트</span>\n        <ev-toggle v-model=\"syncHoverChart3\" />\n        <span>네번째 차트</span>\n        <ev-toggle v-model=\"syncHoverChart4\" />\n      </div>\n      <br>\n      <br>\n      <ev-toggle v-model=\"isLive\" />\n      <span>데이터 자동 업데이트</span>\n      <br>\n      <br>\n      <ev-button @click=\"toggleSelectData\">\n        select by v-model\n      </ev-button>\n      <span class=\"left\">\n        차트 클릭이 아닌 v-model:selectedLabel 에 바인딩한 dataIndex 배열을 변경해서 라벨 선택\n      </span>\n      <br>\n      <br>\n      <ev-toggle v-model=\"isFixedPosTop\" />\n      <span class=\"left\">\n        tip 위치를 최상단에 고정\n      </span>\n      <br>\n      <br>\n      <ev-button @click=\"toggleOverflow\">\n        Deselect Overflow\n      </ev-button>\n      <span class=\"left\">\n        설정한 limit 를 넘어서 클릭했을때 선입선출로 deselect 를 할지를 옵션으로 선택 가능\n      </span>\n      <br>\n      <br>\n      <ev-button @click=\"updateData\">\n        Update Data\n      </ev-button>\n      <span class=\"left\">\n        차트 데이터를 변경하면 팁의 위치만 변경, 라벨은 고정\n      </span>\n      <br>\n      <br>\n      <div>\n        <div class=\"badge yellow\">\n          v-model:selectedLabel\n        </div>\n        {{ defaultSelectLabel }}\n        <br>\n        <br>\n        <div class=\"badge yellow\">\n          클릭 이벤트 데이터 (selected)\n        </div>\n        {{ clickedLabel }}\n        <br>\n        <br>\n      </div>\n    </div>\n  </ev-chart-group>\n</template>\n\n<script>\nimport { ref, reactive, onMounted, watch, onBeforeUnmount } from 'vue';\nimport dayjs from 'dayjs';\n\nexport default {\n  components: {},\n\n  setup() {\n    const groupHoveredLabel = ref();\n    const chart = ref(null);\n\n    const chartData1 = reactive({\n      series: {\n        series1: { name: 'series#1' },\n        series2: { name: 'series#2' },\n      },\n      labels: [],\n      groups: [['series1', 'series2']],\n      data: {\n        series1: [],\n        series2: [],\n      },\n    });\n    const chartData2 = reactive({\n      series: {\n        series1: { name: 'series#1' },\n        series2: { name: 'series#2' },\n      },\n      labels: [],\n      groups: [['series1', 'series2']],\n      data: {\n        series1: [],\n        series2: [],\n      },\n    });\n    const chartData3 = reactive({\n      series: {\n        series1: { name: 'series#1' },\n        series2: { name: 'series#2' },\n      },\n      labels: [],\n      data: {\n        series1: [],\n        series2: [],\n      },\n    });\n    const chartData4 = reactive({\n      series: {\n        series1: { name: 'series#1' },\n        series2: { name: 'series#2' },\n      },\n      labels: [],\n      groups: [['series1', 'series2']],\n      data: {\n        series1: [],\n        series2: [],\n      },\n    });\n\n    const isFixedPosTop = ref(false);\n\n    const syncHoverChart1 = ref(true);\n\n    const chartOptions1 = ref({\n      syncHover: syncHoverChart1.value,\n      type: 'bar',\n      thickness: 0.8,\n      width: '100%',\n      horizontal: false,\n      title: {\n        show: false,\n      },\n      legend: {\n        show: true,\n        position: 'right',\n      },\n      axesX: [{\n        type: 'time',\n        showGrid: false,\n        categoryMode: true,\n        timeFormat: 'mm:ss',\n        interval: 'second',\n      }],\n      axesY: [{\n        showAxis: true,\n        type: 'linear',\n        startToZero: true,\n        autoScaleRatio: 0.1,\n        showGrid: false,\n      }],\n      selectLabel: {\n        use: true,\n        limit: 2,\n        useDeselectOverflow: true,\n        showTip: true,\n        fixedPosTop: isFixedPosTop,\n        useApproximateValue: true,\n        tipBackground: '#FF0000',\n        useSeriesOpacity: true,\n        useLabelOpacity: true,\n      },\n      maxTip: {\n        use: true,\n        showTextTip: true,\n        tipStyle: {\n          background: '#FF0000',\n        },\n      },\n      indicator: {\n        color: '#626872',\n        segments: [4, 2],\n      },\n    });\n\n    watch(syncHoverChart1, (newSyncHover) => {\n      chartOptions1.value.syncHover = newSyncHover;\n    });\n\n    const syncHoverChart2 = ref(true);\n\n    const chartOptions2 = ref({\n      syncHover: syncHoverChart2.value,\n      type: 'bar',\n      thickness: 0.8,\n      width: '100%',\n      horizontal: false,\n      title: {\n        show: false,\n      },\n      legend: {\n        show: true,\n        position: 'right',\n      },\n      axesX: [{\n        type: 'time',\n        showGrid: false,\n        categoryMode: true,\n        timeFormat: 'mm:ss',\n        interval: 'second',\n      }],\n      axesY: [{\n        showAxis: true,\n        type: 'linear',\n        startToZero: true,\n        autoScaleRatio: 0.1,\n        showGrid: false,\n      }],\n      selectLabel: {\n        use: true,\n        limit: 2,\n        useDeselectOverflow: true,\n        showTip: true,\n        fixedPosTop: isFixedPosTop,\n        useApproximateValue: true,\n        tipBackground: '#FF0000',\n        useSeriesOpacity: true,\n        useLabelOpacity: true,\n      },\n      maxTip: {\n        use: true,\n        showTextTip: true,\n        tipStyle: {\n          background: '#FF0000',\n        },\n      },\n      indicator: {\n        color: '#626872',\n        segments: [4, 2],\n      },\n    });\n\n    watch(syncHoverChart2, (newSyncHover) => {\n      chartOptions2.value.syncHover = newSyncHover;\n    });\n\n    const syncHoverChart3 = ref(true);\n\n    const chartOptions3 = ref({\n      syncHover: syncHoverChart3.value,\n      type: 'bar',\n      thickness: 0.8,\n      width: '100%',\n      horizontal: true,\n      title: {\n        show: false,\n      },\n      legend: {\n        show: true,\n        position: 'right',\n      },\n      axesY: [{\n        type: 'time',\n        showGrid: false,\n        categoryMode: true,\n        timeFormat: 'mm:ss',\n        interval: 'second',\n      }],\n      axesX: [{\n        showAxis: true,\n        type: 'linear',\n        startToZero: true,\n        autoScaleRatio: 0.1,\n        showGrid: false,\n      }],\n      selectLabel: {\n        use: true,\n        limit: 2,\n        useDeselectOverflow: true,\n        showTip: true,\n        fixedPosTop: isFixedPosTop,\n        useApproximateValue: true,\n        tipBackground: '#FF0000',\n        useSeriesOpacity: true,\n        useLabelOpacity: true,\n      },\n      maxTip: {\n        use: true,\n        showTextTip: true,\n        tipStyle: {\n          background: '#FF0000',\n        },\n      },\n      indicator: {\n        color: '#626872',\n        segments: [4, 2],\n      },\n    });\n\n    watch(syncHoverChart3, (newSyncHover) => {\n      chartOptions3.value.syncHover = newSyncHover;\n    });\n\n    const syncHoverChart4 = ref(true);\n\n    const chartOptions4 = ref({\n      syncHover: syncHoverChart4.value,\n      type: 'bar',\n      thickness: 0.8,\n      width: '100%',\n      horizontal: true,\n      title: {\n        show: false,\n      },\n      legend: {\n        show: true,\n        position: 'right',\n      },\n      axesY: [{\n        type: 'time',\n        showGrid: false,\n        categoryMode: true,\n        timeFormat: 'mm:ss',\n        interval: 'second',\n      }],\n      axesX: [{\n        showAxis: true,\n        type: 'linear',\n        startToZero: true,\n        autoScaleRatio: 0.1,\n        showGrid: false,\n      }],\n      selectLabel: {\n        use: true,\n        limit: 2,\n        useDeselectOverflow: true,\n        showTip: true,\n        fixedPosTop: isFixedPosTop,\n        useApproximateValue: true,\n        tipBackground: '#FF0000',\n        useSeriesOpacity: true,\n        useLabelOpacity: true,\n      },\n      maxTip: {\n        use: true,\n        showTextTip: true,\n        tipStyle: {\n          background: '#FF0000',\n        },\n      },\n      indicator: {\n        color: '#626872',\n        segments: [4, 2],\n      },\n    });\n\n    watch(syncHoverChart4, (newSyncHover) => {\n      chartOptions4.value.syncHover = newSyncHover;\n    });\n\n    const clickedLabel = ref();\n    const onClick = ({ selected }) => {\n      clickedLabel.value = selected;\n    };\n\n    const defaultSelectItem = ref({\n      seriesID: 'series1',\n      dataIndex: 1,\n    });\n    const defaultSelectLabel = ref({\n      dataIndex: [0],\n    });\n\n    const toggleSelectData = () => {\n      const arr = defaultSelectLabel.value.dataIndex;\n      const newIndex = (arr.pop() + 1) % 9;\n      if (!arr.includes(newIndex)) {\n        arr.push(newIndex);\n      }\n    };\n\n    const toggleOverflow = () => {\n      const b = chartOptions1.value.selectLabel.useDeselectOverflow;\n      chartOptions1.value.selectLabel.useDeselectOverflow = !b;\n      chartOptions2.value.selectLabel.useDeselectOverflow = !b;\n      chartOptions3.value.selectLabel.useDeselectOverflow = !b;\n      chartOptions4.value.selectLabel.useDeselectOverflow = !b;\n    };\n\n    const updateData = () => {\n      const getRandArr = count => Array(count)\n        .fill(0).map(() => Math.ceil(Math.random() * 100));\n\n      const chartList = [chartData1, chartData2, chartData3, chartData4];\n      chartList.forEach((c) => {\n        const seriesList = ['series1', 'series2'];\n        seriesList.forEach((sId) => {\n          c.value.data[sId] = getRandArr(5);\n        });\n      });\n    };\n\n    const syncHover = ref(true);\n\n    const isLive = ref(false);\n    const liveInterval = ref();\n    let timeValue = dayjs().format('YYYY-MM-DD HH:mm:ss');\n\n    const addRandomChartData = () => {\n      if (isLive.value) {\n        chartData1.labels.shift();\n        chartData2.labels.shift();\n        chartData3.labels.shift();\n        chartData4.labels.shift();\n      }\n\n      timeValue = dayjs(timeValue).add(6, 'second');\n      chartData1.labels.push(dayjs(timeValue));\n      chartData2.labels.push(dayjs(timeValue));\n      chartData3.labels.push(dayjs(timeValue));\n      chartData4.labels.push(dayjs(timeValue));\n\n      Object.values(chartData1.data).forEach((seriesData) => {\n        if (isLive.value) {\n          seriesData.shift();\n        }\n        seriesData.push(Math.floor(Math.random() * ((5000 - 5) + 1)) + 5);\n      });\n      Object.values(chartData2.data).forEach((seriesData) => {\n        if (isLive.value) {\n          seriesData.shift();\n        }\n        seriesData.push(Math.floor(Math.random() * ((5000 - 5) + 1)) + 5);\n      });\n      Object.values(chartData3.data).forEach((seriesData) => {\n        if (isLive.value) {\n          seriesData.shift();\n        }\n        seriesData.push(Math.floor(Math.random() * ((5000 - 5) + 1)) + 5);\n      });\n      Object.values(chartData4.data).forEach((seriesData) => {\n        if (isLive.value) {\n          seriesData.shift();\n        }\n        seriesData.push(Math.floor(Math.random() * ((5000 - 5) + 1)) + 5);\n      });\n    };\n\n    onMounted(() => {\n      for (let ix = 0; ix < 10; ix++) {\n        addRandomChartData();\n      }\n    });\n\n    watch(isLive, (newValue) => {\n      if (newValue) {\n        addRandomChartData();\n        liveInterval.value = setInterval(addRandomChartData, 2000);\n      } else {\n        clearInterval(liveInterval.value);\n      }\n    });\n\n    onBeforeUnmount(() => {\n      clearInterval(liveInterval.value);\n    });\n\n    return {\n      syncHover,\n      syncHoverChart1,\n      syncHoverChart2,\n      syncHoverChart3,\n      syncHoverChart4,\n      isLive,\n      groupHoveredLabel,\n      chart,\n      chartData1,\n      chartData2,\n      chartData3,\n      chartData4,\n      isFixedPosTop,\n      chartOptions1,\n      chartOptions2,\n      chartOptions3,\n      chartOptions4,\n      clickedLabel,\n      defaultSelectItem,\n      defaultSelectLabel,\n      onClick,\n      toggleSelectData,\n      toggleOverflow,\n      updateData,\n    };\n  },\n};\n</script>\n\n<style lang=\"scss\" scoped>\n  .description {\n    position: relative;\n  }\n  .left {\n    position: absolute;\n    left: 160px;\n    padding-top: 10px;\n  }\n  .hover-options {\n    display: flex;\n    align-items: center;\n  }\n</style>\n";