export default "<template>\n  <div class=\"case\">\n    <ev-tree-grid\n      v-model:selected=\"selected\"\n      v-model:checked=\"checked\"\n      :columns=\"gridColumns\"\n      :rows=\"tableData\"\n      :width=\"widthMV\"\n      :height=\"heightMV\"\n      :option=\"{\n        adjust: true,\n        useGridSetting: {\n          use: true,\n          useDefaultColumnSetting: false,\n          customContextMenu: gridSettingMenuItems,\n        },\n      }\"\n      @resize-column=\"onUpdateColumns\"\n      @change-column-status=\"onUpdateColumns\"\n    >\n    </ev-tree-grid>\n    <custom-column-list\n      v-model:columns=\"gridColumns\"\n      v-model:is-visible=\"isVisible\"\n    />\n  </div>\n</template>\n\n<script>\nimport { ref } from 'vue';\nimport CustomColumnList from 'docs/views/grid/example/partitals/CustomColumnList.vue';\n\nexport default {\n  components: { CustomColumnList },\n  setup() {\n    const isVisible = ref(false);\n    const tableData = ref([]);\n    const selected = ref([]);\n    const checked = ref([]);\n    const widthMV = ref('100%');\n    const heightMV = ref(300);\n    const gridSettingMenuItems = ref([\n      {\n        text: 'Menu1',\n        click: param => console.log(`[Menu1]: ${param}`),\n      }, {\n        text: 'Custom Column List',\n        click: () => {\n          isVisible.value = true;\n        },\n      },\n    ]);\n    const getData = () => {\n      tableData.value = [\n        {\n          id: 'Exem 0',\n          date: '2016-05-01',\n          name: '1111',\n          expand: true,\n        },\n        {\n          id: 'Exem 1',\n          date: '2016-05-01',\n          name: '2222',\n          value: 123,\n          expand: true,\n          children: [{\n            id: 'Exem 2',\n            date: '2016-05-02',\n            name: '2',\n            value: 222,\n            expand: false,\n            children: [{\n              id: 'Exem 3',\n              date: '2016-05-02',\n              name: '3',\n              value: 3333,\n              uncheckable: true,\n            }, {\n              id: 'Exem 4',\n              date: '2016-05-02',\n              name: '4',\n              expand: false,\n              uncheckable: true,\n              children: [{\n                id: 'Exem 5',\n                date: '2016-05-02',\n                name: '5',\n                children: [{\n                  id: 'Exem 51',\n                  date: '2016-05-02',\n                  name: '1251',\n                  children: [{\n                    id: 'Exem 52',\n                    date: '2016-05-02',\n                    name: '20000',\n                  }],\n                }],\n              }, {\n                id: 'Exem 6',\n                date: '2016-05-02',\n                name: '6',\n              }],\n            }],\n          }, {\n            id: 'Exem 7',\n            date: '2016-05-03',\n            name: '7',\n            children: [{\n              id: 'Exem 8',\n              date: '2016-05-03',\n              name: '8',\n              value: 333,\n            }, {\n              id: 'Exem 9',\n              date: '2016-05-03',\n              name: '9',\n            }, {\n              id: 'Exem 10',\n              date: '2016-05-03',\n              name: '10',\n            }],\n          }, {\n            id: 'Exem 11',\n            date: '2016-05-04',\n            name: '11',\n          }],\n        },\n      ];\n    };\n    const gridColumns = ref([\n      { caption: 'ID', field: 'id', type: 'number' },\n      { caption: 'Date', field: 'date', type: 'string' },\n      {\n        caption: 'Name',\n        field: 'name',\n        type: 'float',\n        summaryType: 'sum',\n        summaryOnlyTopParent: true,\n        summaryRenderer: 'Sum: {0} 최상위 부모만 summary',\n        decimal: 1,\n      },\n      {\n        caption: 'Value',\n        field: 'value',\n        type: 'number',\n        summaryType: 'sum',\n        summaryRenderer: 'Sum: {0} 모든 row summary',\n        decimal: 1,\n      },\n    ]);\n\n    const onUpdateColumns = ({ columns }) => {\n      gridColumns.value = columns;\n    };\n\n    getData();\n    return {\n      isVisible,\n      gridColumns,\n      tableData,\n      selected,\n      checked,\n      widthMV,\n      heightMV,\n      gridSettingMenuItems,\n      onUpdateColumns,\n    };\n  },\n};\n</script>\n\n<style lang=\"scss\" scoped>\n.description {\n  min-width: 200px;\n}\n.form-rows {\n  display: flex;\n  margin-bottom: 5px;\n}\n.form-row {\n  width: 50%;\n}\n.ev-text-field, .ev-input-number, .ev-select {\n  width: 80%;\n}\n.badge {\n  margin-bottom: 2px;\n  margin-right: 5px !important;\n}\n.ev-toggle {\n  margin-right: 10px;\n}\n</style>\n";